"""moy2line_widget.py — the moy-2 reflection-tool line explainer as a native anywidget (no iframe). The front-end (dist/widget.js, dist/widget.css) is generated by build.mjs.

    from moy2line_widget import Moy2Line, kernel_recount
    w = Moy2Line(state=0)                    # JupyterLab: put `w` at the end of a cell.   marimo: mo.ui.anywidget(w)
    w.state = 8; w.row = "olm125:b0_j16"     # kernel -> figure: walk to the rack and pick a row
    w.arm = "olm119"; w.lang = "en"; w.theme = "light"
    w.state, w.row, w.arm, w.done            # figure -> kernel: what the reader pressed / dragged, and whether the figure has drawn
    w.reading                                # figure -> kernel: what is on the screen (kicker, readout, chips, the side panel's text)
    kernel_recount()                         # the THIRD route: the kernel recounts the figure's numbers from the raw inventory rows (not from the pack)
Both directions are tested (run_marimo_check.sh): a value the figure writes comes back to Python, and a value written in Python moves the figure.
"""
import json
import pathlib

import anywidget
import traitlets

HERE = pathlib.Path(__file__).resolve().parent
CONFIG = json.loads((HERE / "config.json").read_text(encoding="utf-8"))
STATES = CONFIG["chapters"][-1][2] + 1        # the number of states is never typed: the last state of the last chapter in config.json


class Moy2Line(anywidget.AnyWidget):
    _esm = HERE / "dist" / "widget.js"
    _css = HERE / "dist" / "widget.css"
    state = traitlets.Int(0).tag(sync=True)
    lang = traitlets.Enum(["ja", "en"], default_value="ja").tag(sync=True)
    theme = traitlets.Enum(["dark", "light", "auto"], default_value="dark").tag(sync=True)
    row = traitlets.Unicode("").tag(sync=True)                   # "olm125:b1_j17" — the picked row of the rack (states 8, 11, 12, 13; v1.1)
    arm = traitlets.Unicode("").tag(sync=True)                   # "olm125" — the picked arm of the scale (state 6)
    done = traitlets.Bool(True).tag(sync=True)
    reading = traitlets.Dict({}).tag(sync=True)

    @traitlets.validate("state")
    def _clamp_state(self, proposal):
        return max(0, min(STATES - 1, int(proposal["value"])))


def kernel_recount():
    """the kernel side of the recount: from the raw inventory rows, the proof-field line symmetry (v3 / v6), parsed rows, calc rows, rejects and the b2_j07 type per arm"""
    inv = json.loads((HERE / "data" / "moy2_line_inventory.json").read_text(encoding="utf-8"))
    out = {}
    for arm, a in inv["arms"].items():
        rows = a["rows"]
        pf = [r for r in rows if r["has_proof"]]
        ln3 = sum(1 for r in pf if (r["proof_v3"] or {}).get("LN_a"))
        ln6 = sum(1 for r in pf if (r["proof_v6"] or {}).get("LN6_a"))
        out[arm] = {"v3": f"{ln3} / {len(pf)} = {ln3 / len(pf):.3f}", "v6": f"{ln6} / {len(pf)} = {ln6 / len(pf):.3f}", "parsed": sum(1 for r in rows if r["cls"] != "NONE"),
                    "calc": sum(1 for r in rows if r["calc"]), "rej": sum(1 for r in rows if r["rej6"]), "typ": [r["key"] for r in rows if r["rej6_then_proof_LN6"]]}
    return out
